function createApp(dataPath, initialStore) {
  let store = initialStore;
  let queue = Promise.resolve();

  // Runs mutations one at a time. The returned promise carries the task's own
  // result or error to the caller; the chain itself only needs to keep going.
  function serialize(task) {
    const run = queue.then(task);
    queue = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  async function commit(next) {
    await saveStore(dataPath, next);
    store = next;
  }

  function listBookings(res, query) {
    const params = new URLSearchParams(query);
    let bookings = store.bookings;
    if (params.has('date')) {
      const date = params.get('date');
      if (!isValidDate(date)) return sendError(res, 400, MSG.date);
      bookings = bookings.filter((b) => b.date === date);
    }
    return sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
  }

  async function createBooking(req, res, body) {
    if (mediaType(req.headers['content-type']) !== 'application/json') {
      return sendError(res, 415, MSG.contentType);
    }
    if (body.size > MAX_BODY_BYTES) return sendError(res, 413, MSG.tooLarge);
    const input = parseObject(body.buffer);
    if (input === null) return sendError(res, 400, MSG.notObject);
    const invalid = fieldError(input);
    if (invalid !== null) return sendError(res, 400, invalid);
    const fields = {
      room: input.room,
      title: input.title.trim(),
      date: input.date,
      start: input.start,
      end: input.end,
    };
    return serialize(async () => {
      const clash = store.bookings
        .filter((b) => overlaps(b, fields))
        .sort((a, b) => (a.start < b.start ? -1 : a.start > b.start ? 1 : 0))[0];
      if (clash) {
        return sendError(res, 409, `room is already booked from ${clash.start} to ${clash.end}`);
      }
      const booking = Object.freeze({ id: store.nextId, ...fields });
      await commit(
        Object.freeze({
          nextId: store.nextId + 1,
          bookings: Object.freeze([...store.bookings, booking]),
        }),
      );
      return sendJson(res, 201, booking);
    });
  }

  function deleteBooking(res, idText) {
    return serialize(async () => {
      const found =
        /^[1-9][0-9]*$/.test(idText) && store.bookings.some((b) => String(b.id) === idText);
      if (!found) return sendError(res, 404, MSG.bookingNotFound);
      await commit(
        Object.freeze({
          nextId: store.nextId,
          bookings: Object.freeze(store.bookings.filter((b) => String(b.id) !== idText)),
        }),
      );
      return sendNoContent(res);
    });
  }

  async function serveStatic(res, entry) {
    const content = await readFile(join(PUBLIC_DIR, entry.file));
    res.writeHead(200, { 'Content-Type': entry.type, 'Content-Length': content.length });
    res.end(content);
  }

  async function route(req, res, body) {
    const target = req.url ?? '';
    const qIndex = target.indexOf('?');
    const path = qIndex === -1 ? target : target.slice(0, qIndex);
    const query = qIndex === -1 ? '' : target.slice(qIndex + 1);
    const method = req.method;

    if (path === '/api/rooms') {
      return method === 'GET' ? sendJson(res, 200, { rooms: [...ROOMS] }) : sendError(res, 405, MSG.method);
    }
    if (path === '/api/bookings') {
      if (method === 'GET') return listBookings(res, query);
      if (method === 'POST') return createBooking(req, res, body);
      return sendError(res, 405, MSG.method);
    }
    if (path.startsWith(BOOKINGS_PREFIX)) {
      const idText = path.slice(BOOKINGS_PREFIX.length);
      if (idText === '' || idText.includes('/')) return sendError(res, 404, MSG.notFound);
      return method === 'DELETE' ? deleteBooking(res, idText) : sendError(res, 405, MSG.method);
    }
    if (Object.hasOwn(STATIC_FILES, path)) {
      return method === 'GET' ? serveStatic(res, STATIC_FILES[path]) : sendError(res, 405, MSG.method);
    }
    return sendError(res, 404, MSG.notFound);
  }

  function replyInternalError(res) {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    sendError(res, 500, MSG.internal);
  }

  return async function handle(req, res) {
    try {
      const body = await readBody(req);
      await route(req, res, body);
    } catch {
      // Any unexpected failure (save error, unreadable page, broken request)
      // becomes a generic 500; details are never sent to the client.
      replyInternalError(res);
    }
  };
}

